CREATE TABLE IF NOT EXISTS gis_current_exception_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version text NOT NULL, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, state_code text, category text NOT NULL, status text NOT NULL DEFAULT 'OPEN', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id));